/**
 * Documentation generated by Gemini
 * Screen providing system administrators with search and deletion capabilities over user profiles.
 *
 * @param navController Navigation controller for routing back to dashboard.
 * @param userState Current user profile state.
 * @param userRepository Repository interface for user data operations.
 */
@Composable
fun AdminProfilesScreen(
    navController: NavController,
    userState: UserState,
    userRepository: UserRepository
) {

    val backgroundColor = Color(0xFFFEFAE0)
    val buttonColor = Color(0xFF283618)

    var searchText by remember { mutableStateOf("") }
    val profiles = remember { mutableStateListOf<Map<String, Any>>() }
    var errorMessage by remember { mutableStateOf<String?>(null) }
    var selectedProfile by remember { mutableStateOf<String>("") }


    // get all profiles, fetch live changes
    DisposableEffect(userRepository) {

        val listener = userRepository.getUsers(
            onSuccess = { users ->
                profiles.clear()
                profiles.addAll(users)
            },
            onFailure = { exception ->
                errorMessage = exception.message
            }
        )

        onDispose {
            listener.remove()
        }
    }

    // filter profiles
    val filteredProfiles = profiles.filter { profile ->

        val name = profile["name"] as? String ?: ""
        val email = profile["email"] as? String ?: ""
        val phoneNumber = profile["phoneNumber"] as? String ?: ""

        name.contains(searchText, ignoreCase = true) ||
                email.contains(searchText, ignoreCase = true) ||
                phoneNumber.contains(searchText, ignoreCase = true)
    }


    //Column to display all the users
    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(backgroundColor)
            .padding(16.dp),
        horizontalAlignment = Alignment.CenterHorizontally,

        ) {

        // Row for back button, header and notif log
        Row(
            modifier = Modifier
                .fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Button(
                onClick = { navController.popBackStack() },
                shape = RoundedCornerShape(8.dp),
                colors = ButtonDefaults.buttonColors(
                    containerColor = buttonColor
                ),
                modifier = Modifier
                    .testTag("backButton")

            ) {
                Text("< Back")
            }

            Text(
                text = "Profiles",
                fontSize = 35.sp
            )



            Button(
                onClick = {
                    if (selectedProfile.isNotEmpty() && userState is UserState.Ready) {
                        userRepository.deleteUser(
                            selectedProfile,
                            onSuccess = {
                                selectedProfile = ""
                            },
                            onFailure = {
                                selectedProfile = ""

                            },
                        )
                    }
                },
                shape = RoundedCornerShape(8.dp),
                colors = ButtonDefaults.buttonColors(
                    containerColor = buttonColor
                ),
                modifier = Modifier.testTag("deleteButton")

            ) {

                Text("Delete")
            }

        }

        Spacer(modifier = Modifier.height(24.dp))

        // Search bar and filter button
        Row(
            modifier = Modifier
                .fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(6.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            BasicTextField(
                value = searchText,
                onValueChange = { searchText = it },
                singleLine = true,
                textStyle = TextStyle(
                    fontSize = 16.sp,
                    color = buttonColor,
                    textAlign = TextAlign.Center
                ),
                modifier = Modifier
                    .weight(1f)
                    .height(42.dp)
                    .border(2.dp, buttonColor)
                    .padding(8.dp)
                    .wrapContentHeight(Alignment.CenterVertically),
                decorationBox = { innerTextField ->
                    Box(
                        contentAlignment = Alignment.Center
                    ) {
                        if (searchText.isEmpty()) {
                            Text(
                                "Search...",
                                color = buttonColor,
                                fontSize = 16.sp
                            )
                        }
                        innerTextField()
                    }
                }
            )
        }

        Spacer(modifier = Modifier.height(24.dp))

        // LazyColumn for scrolling profiles view
        LazyColumn(
            modifier = Modifier
                .fillMaxWidth()
                .weight(1f),
        ) {

            items(filteredProfiles) { profile ->
                val profileName = profile["name"] as? String ?: "Unknown User"
                val profileEmail = profile["email"] as? String ?: "No Email"
                val profilePhoneNumber = profile["phoneNumber"] as? String ?: "No Number"
                val userId = profile["userId"] as? String ?: "" // should never fail

                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable {
                            if (selectedProfile == userId) {
                                selectedProfile = ""
                            }
                            else {
                                selectedProfile = userId
                            }
                        }
                        .background(
                            if (selectedProfile == userId)
                                buttonColor.copy(alpha = 0.3f)
                            else backgroundColor
                        )
                        .height(70.dp)
                        .padding(horizontal = 12.dp)
                        .border(1.dp, buttonColor),
                ) {
                    Column(
                        modifier = Modifier.fillMaxSize()
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(4.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {

                            Text(profileName)
                            Text(profileEmail)

                        }

                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(4.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {

                            Text(
                                text = "Tel:$profilePhoneNumber"
                            )


                        }
                    }



                }
            }


        }

    }
}


